(function(){const layer=document.getElementById('particleLayer');const hearts=document.getElementById('floatingHearts');function burst(source,amount=22){const rect=source.getBoundingClientRect();for(let i=0;i<amount;i+=1){const particle=document.createElement('span');particle.className='burst-particle';particle.textContent=i%3?'♡':'✦';particle.style.left=`${rect.left+rect.width/2}px`;particle.style.top=`${rect.top+rect.height/2}px`;particle.style.setProperty('--x',`${(Math.random()-.5)*300}px`);particle.style.setProperty('--y',`${(Math.random()-.5)*260}px`);particle.style.setProperty('--r',`${(Math.random()-.5)*90}deg`);particle.addEventListener('animationend',()=>particle.remove(),{once:true});layer.appendChild(particle)}}for(let i=0;i<10;i+=1){const heart=document.createElement('span');heart.textContent=i%4?'♡':'✦';heart.style.left=`${Math.random()*100}%`;heart.style.animationDelay=`${Math.random()*-14}s`;heart.style.animationDuration=`${12+Math.random()*8}s`;hearts.appendChild(heart)}window.Effects={burst}})();
